import assert from 'node:assert/strict';import fs from 'node:fs';import {curve,sweep} from '../src/geometry.js';
const path=curve([[0,0,0],[0,2,0]]),segments=20,sides=24,stride=sides+1,rings=segments+1,reports=[];
for(const [hollow,holes] of [[false,[]],[true,[]],[true,[{u:.02,t:.75,w:.16,h:.15}]]]){const g=sweep(path,.4,{segments,sides,tip:1,lobes:0,hollow,holes}),p=g.attributes.position,n=g.attributes.normal,ix=g.index.array;let volume=0;for(let k=0;k<ix.length;k+=3){const a=ix[k],b=ix[k+1],c=ix[k+2];volume+=(p.getX(a)*(p.getY(b)*p.getZ(c)-p.getZ(b)*p.getY(c))+p.getY(a)*(p.getZ(b)*p.getX(c)-p.getX(b)*p.getZ(c))+p.getZ(a)*(p.getX(b)*p.getY(c)-p.getY(b)*p.getX(c)))/6;}assert.ok(volume>0,'closed tube must enclose positive oriented volume');let out=[],inner=[];for(let j=1;j<sides;j++){const i=10*stride+j;const dot=q=>(p.getX(q)*n.getX(q)+p.getZ(q)*n.getZ(q))/Math.hypot(p.getX(q),p.getZ(q));out.push(dot(i));assert.ok(dot(i)>.95,'outer normals point radially outward');if(hollow){inner.push(dot(i+rings*stride));assert.ok(dot(i+rings*stride)<-.95,'inner normals point into hollow');}}
 if(!hollow){assert.ok(n.getY(p.count-2)<-.99,'base cap faces backwards');assert.ok(n.getY(p.count-1)>.99,'tip cap faces forwards');}
 // Canonical coincident vertices close the periodic UV seam without adding an
 // internal radial divider. Every welded edge of this closed fixture is paired.
 const verts=new Map(),canonical=[];for(let i=0;i<p.count;i++){const key=[p.getX(i),p.getY(i),p.getZ(i)].map(v=>Math.round(v*1e6)).join(',');if(!verts.has(key))verts.set(key,verts.size);canonical[i]=verts.get(key);}const edges=new Map();for(let k=0;k<ix.length;k+=3)for(let j=0;j<3;j++){const a=canonical[ix[k+j]],b=canonical[ix[k+(j+1)%3]],key=Math.min(a,b)+','+Math.max(a,b);edges.set(key,(edges.get(key)||0)+1);}assert.ok([...edges.values()].every(n=>n===2),'closed geometric edges exactly twice');reports.push({hollow,holes:holes.length,volume,outerMin:Math.min(...out),innerMax:inner.length?Math.max(...inner):null,geometricallyWatertight:true,triangles:ix.length/3});}
fs.writeFileSync(new URL('../qa/sweep-orientation-report.json',import.meta.url),JSON.stringify({pass:true,reports},null,2)+'\n');console.log('PASS outward/inner/cap normals, positive volume, closed UV seam',reports);
